ribbons = {}
def tie(face, variant, src):
    ribbons.setdefault(face, []).append((variant, src))
tie("loom", "Loom", "shed-a"); tie("loom", "LOOM", "shed-b")
print(ribbons["loom"])
assert len(ribbons["loom"]) == 2

law = {"tool": ["purpose"]}
cloth = {"loom": {"kind": "tool", "purpose": "weave"}, "rock": {"kind": "tool"}}
flawed = [k for k, a in cloth.items() if any(r not in a for r in law[a["kind"]])]
print("flawed knots:", flawed)
assert flawed == ["rock"]

threads = [("a", "b")]
knots = {"a", "b", "stray"}
tied = {k for t in threads for k in t}
print("strays:", knots - tied)
assert knots - tied == {"stray"}
